import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';import '../../../services/personal_ai/habit_service.dart';
class AurenHabitScreen extends StatefulWidget{const AurenHabitScreen({super.key});@override State<AurenHabitScreen> createState()=>_AurenHabitScreenState();}
class _AurenHabitScreenState extends State<AurenHabitScreen>{final name=TextEditingController();final service=HabitService();
Future<void> add(String uid)async{if(name.text.trim().isEmpty)return;await service.create(uid,name.text);name.clear();}
@override void dispose(){name.dispose();super.dispose();}
@override Widget build(BuildContext c){final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null)return const Scaffold(body:Center(child:Text('يجب تسجيل الدخول')));return Scaffold(appBar:AppBar(title:const Text('Habits')),body:StreamBuilder<List<AurenHabit>>(stream:service.watch(uid),builder:(c,s){final hs=s.data??const[];return ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'عادة جديدة',prefixIcon:Icon(Icons.add_task)),onSubmitted:(_)=>add(uid)),const SizedBox(height:8),FilledButton.icon(onPressed:()=>add(uid),icon:const Icon(Icons.add),label:const Text('إضافة')),const SizedBox(height:12),if(hs.isEmpty)const Padding(padding:EdgeInsets.all(24),child:Text('ابدأ بعادة صغيرة يومية.')),...hs.map((h)=>Card(child:ListTile(title:Text(h.name),subtitle:Text('السلسلة الحالية: ${h.streak} يوم'),leading:IconButton(icon:Icon(h.dates.contains(_key(DateTime.now().toUtc()))?Icons.check_circle:Icons.radio_button_unchecked),onPressed:()=>service.toggleToday(uid,h)),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='pause')service.setActive(uid,h,!h.active);if(v=='delete')service.delete(uid,h.id);},itemBuilder:(_)=>[PopupMenuItem(value:'pause',child:Text(h.active?'إيقاف':'تفعيل')),const PopupMenuItem(value:'delete',child:Text('حذف'))]))))]);}));}
}
String _key(DateTime d)=>'${d.year.toString().padLeft(4,'0')}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';